def sans_echecs(notes):
    for n in notes:
        if n < 10:
            notes.remove(n)
    return notes

def caisse(articles, remises=[]):
    for a in articles:
        if a[1] == 0:
            articles.remove(a)
    total = sum(a[1] for a in articles) * 1.0
    remises.append(total)
    return [[a[0] for a in articles], round(total), total == 1500.0000000001]
